import math
print(math.floor(9007199254740993), math.ceil(-9007199254740993), math.trunc(2.7), math.gcd(12, -18), math.lcm(4, 6), math.isqrt(99), math.factorial(20), math.comb(50, 25), math.perm(5, 2))
print(math.isfinite(1.0), math.isinf(math.inf), math.isnan(math.nan), math.copysign(1.0, -0.0), math.degrees(math.pi), math.log(8.0, 2.0), math.cbrt(27.0), math.tau)
print(math.pow(2.0, 10.0), math.fmod(7.5, 2.0), math.hypot(3.0, 4.0), math.atan2(1.0, 1.0), math.log1p(1e-10), math.expm1(1e-10), math.exp2(10.0))
